function searchAll(q){let toks=tokenize(q);toks=toks.flatMap(x=>AR_MAP[x]?AR_MAP[x].split(' '):[x]);if(!toks.length)return{o:[],r:[]};
 const sc=(txt,o)=>{let s=0;for(const k of toks){if(txt.includes(k))s+=1;if(o&&o.abbr&&o.abbr.toLowerCase()===k)s+=5;if(o&&(o.name||'').toLowerCase().includes(k))s+=2}return s};
 const o=VIS.map(x=>[sc(idx(x),x),x]).filter(a=>a[0]>=Math.max(1,Math.ceil(toks.length*.6))).sort((a,b)=>b[0]-a[0]).map(a=>a[1]);
 const r=RULES.map(x=>[sc(ridx(x)),x]).filter(a=>a[0]>=Math.max(1,Math.ceil(toks.length*.6))).sort((a,b)=>b[0]-a[0]).map(a=>a[1]);return{o,r}}
