function answer(q){const toks=tokenize(q).flatMap(x=>AR_MAP[x]?[x,...AR_MAP[x].split(' ')]:[x]);const ql=q.toLowerCase();
 let best=null,bs=0;FAQ.forEach(f=>{let s=0;f.k.forEach(k=>{if(ql.includes(k))s+=3});tokenize(f.q).forEach(w=>{if(w.length>3&&toks.includes(w))s+=1});if(s>bs){bs=s;best=f}});
 if(best&&bs>=4)return {kind:'faq',f:best};
 const sr=searchAll(q);if(sr.o.length||sr.r.length)return {kind:'search',sr};return {kind:'none'}}
function ansHTML(a){const lk=(o)=>`<a class="tag" href="#/org/${o}">${esc(ORG[o].abbr||ORG[o].name)}</a>`;
 if(a.kind==='faq'){const f=a.f;return `<b>${esc(fq(f,'q'))}</b><p>${esc(fq(f,'a'))}</p><p><b>${ar()?'مثال عملي':'Practical example'}:</b> ${esc(fq(f,'ex'))}</p><p><b>${ar()?'الجهات':'Organizations'}:</b> ${f.orgs.filter(x=>ORG[x]).map(lk).join('')}</p>${f.rules.length?`<p><b>${ar()?'القواعد':'Applicable rules'}:</b> ${f.rules.filter(x=>RUL[x]).map(x=>`<a class="tag" href="#/rule/${x}">${esc(rt(RUL[x],'t').slice(0,48))}</a>`).join('')}</p>`:''}<p><b>${ar()?'المصادر الرسمية':'Official sources'}:</b> ${f.orgs.filter(x=>ORG[x]&&ORG[x].site).slice(0,4).map(x=>`<a href="${esc(href(ORG[x].site))}" target="_blank" rel="noopener">${esc(host(ORG[x].site))}</a>`).join(' · ')}</p><p class="desc">${t('disc')}</p>`}
 if(a.kind==='search'){const o=a.sr.o.slice(0,4);const r=a.sr.r.slice(0,3);return `<p>${ar()?'لا توجد إجابة جاهزة موثقة لهذا السؤال. هذه أقرب السجلات في قاعدة البيانات:':'There is no prepared verified answer for this question. These are the closest records in the database:'}</p>${o.map(x=>`<p><b>${lk(x.id)}</b> ${esc(x.name)}: ${esc(x.desc.slice(0,220))}</p>`).join('')}${r.map(x=>`<p>📄 <a href="#/rule/${x.id}">${esc(x.title)}</a>: ${esc(x.scope.slice(0,200))}</p>`).join('')}<p class="desc">${t('disc')}</p>`}
 return `<p>${t('noresults')}</p>`}
